{
  "summary": "The paper introduces SMem (static memory), an architecture that decouples context representation from prefix entanglement by encoding blocks independently and using cross-attention in the reader. SMem achieves exact context composition, deletion, and path-independent editing by construction, while maintaining comparable perplexity to standard transformers. It also demonstrates superior long-range needle retrieval at 4× the training context length and significantly faster serving and deletion speeds.",
  "items": {
    "chk_problem": {
      "value": "The KV cache of transformers entangles token representations with their entire prefix, preventing exact context reuse under different prefixes and exact deletion without recomputing subsequent tokens.",
      "paper_quote": "The KV cache of a transformer entangles every token’s representation with its entire prefix: a passage encoded once cannot be reused under a different prefix, and cannot be removed without recomputing everything after it."
    },
    "chk_method": {
      "value": "SMem (static memory), which encodes blocks of tokens independently into memory rows and uses a reader to condition generation on these rows via cross-attention.",
      "paper_quote": "A block-local encoder maps each block of tokens to memory rows independently of all other blocks; a reader conditions generation on the union of those rows through cross-attention."
    },
    "chk_data": {
      "value": "The FineWeb-Edu dataset used for pretraining the models.",
      "paper_quote": "SMem and a standard pre-LN transformer are pretrained from scratch on FineWeb-Edu (Penedo et al., 2024) (GPT-2 tokenizer, T =1024, b=64, B=16) at ≈20:1 token budgets (Hoffmann et al., 2022): 160M/3.2B tokens (3 seeds per arm), 410M/8.2B (2 seeds), 1.4B/30B (1 seed; we write “1.5B” for the 1.42B-parameter scale)."
    },
    "chk_setup": {
      "value": "Pretraining SMem and standard pre-LN transformers from scratch on FineWeb-Edu at 160M, 410M, and 1.5B parameter scales under two training recipes (Regime 1 and Regime 2).",
      "paper_quote": "SMem and a standard pre-LN transformer are pretrained from scratch on FineWeb-Edu (Penedo et al., 2024) (GPT-2 tokenizer, T =1024, b=64, B=16) at ≈20:1 token budgets (Hoffmann et al., 2022): 160M/3.2B tokens (3 seeds per arm), 410M/8.2B (2 seeds), 1.4B/30B (1 seed; we write “1.5B” for the 1.42B-parameter scale)."
    },
    "chk_primary_result": {
      "value": "SMem retrieves planted needles at 4× the training context with an exact-match accuracy of 0.14–0.28 at distances of 31 and 63 blocks, while transformer variants score at most 0.02.",
      "paper_quote": "At 4× the training context, under the shared training recipe, SMem still retrieves planted needles beyond any window of the trained length (exact-match accuracy 0.14–0.28 at distances 31 and 63 blocks) where a learned-position transformer, a RoPE transformer, a Block-Attention-style two-stream arm, and windowed or saturated readings of the transformers all score at most 0.02; with two identical keys it returns the nearer one’s value."
    },
    "chk_secondary_result": {
      "value": "SMem achieves a perplexity gap of -4.7% to +2.8% compared to a parameter-matched transformer on FineWeb-Edu across two training recipes and a learning-rate search.",
      "paper_quote": "What it costs is a perplexity gap of −4.7% to +2.8% (negative favors SMem) against a parameter-matched transformer with the same positional scheme, at 160M–1.5B on FineWeb-Edu across two training recipes and a learning-rate search; the band’s lower endpoint is set by the recipe and its upper by the learning-rate search, and the recipe’s change moves the transformer twice as far as it moves SMem at 160M."
    },
    "chk_baseline": {
      "value": "A parameter-matched standard pre-LN transformer, along with other variants like RoPE transformers, Block-Attention-style arms, and windowed or saturated transformer readings.",
      "paper_quote": "SMem and a standard pre-LN transformer are pretrained from scratch on FineWeb-Edu (Penedo et al., 2024) (GPT-2 tokenizer, T =1024, b=64, B=16) at ≈20:1 token budgets (Hoffmann et al., 2022): 160M/3.2B tokens (3 seeds per arm), 410M/8.2B (2 seeds), 1.4B/30B (1 seed; we write “1.5B” for the 1.42B-parameter scale)."
    },
    "chk_conclusion": {
      "value": "Dropping prefix entanglement in context representation allows SMem to achieve comparable perplexity to transformers while gaining exact context composition, deletion, and editing, plus superior long-range retrieval.",
      "paper_quote": "Context representation entangled with the full prefix is a design choice; an architecture that drops that entanglement reaches comparable perplexity and gains a cache that composes, deletes, and edits exactly and, under the shared recipe, retrieves at range where every transformer variant we test does not."
    },
    "chk_limitation": {
      "value": "SMem must be chosen at pretraining time rather than being retrofitted, and it exhibits a perplexity gap of -4.7% to +2.8% compared to standard transformers.",
      "paper_quote": "SMem is a pretraining-time choice, not a retrofit."
    }
  }
}
